#!/usr/bin/env python3
"""Update data/facts.yml, the ecosystem numbers behind the {{ facts.* }} placeholders.

Sources:
  - DNS provider support data: statsdata/providers/ in
    https://github.com/pawel-kow/DomainConnectSupportStatsData (manifest.json, overview.json)
  - Template repository data (contributors, PRs, field and record type usage):
    https://stats.domainconnect.org/stats.json, until the data repository publishes
    statsdata/templates/

Usage: update_facts.py [--source DIR] [--output FILE] [--check]
  --source DIR   read statsdata/providers/ from a local checkout of the data repository
                 instead of GitHub
  --output FILE  file to write (default: data/facts.yml in the repository root)
  --check        do not write; exit 1 if the file is out of date

Runs without third-party packages. Exits non-zero if a source cannot be read, leaving
the existing file untouched.
"""

import argparse
import json
import pathlib
import sys
import urllib.request
from datetime import datetime

DATA_REPO_URL = "https://github.com/pawel-kow/DomainConnectSupportStatsData"
DATA_REPO = "https://raw.githubusercontent.com/pawel-kow/DomainConnectSupportStatsData/main"
PROVIDERS_DIR = "statsdata/providers"
TEMPLATE_STATS_URL = "https://stats.domainconnect.org/stats.json"
ROOT = pathlib.Path(__file__).resolve().parents[2]
DEFAULT_OUTPUT = ROOT / "data" / "facts.yml"

HEADER = """\
# Ecosystem facts used by the {{ facts.<key> }} placeholders in Knowledge Base/
# (resolved at build time by hooks/facts.py).
#
# GENERATED by .github/.scripts/update_facts.py — do not edit by hand.
# The build (.github/.scripts/build.sh) refreshes it before building; run the
# script and commit the result to update the committed fallback copy.
"""


def fetch_json(url):
    req = urllib.request.Request(url, headers={"User-Agent": "dc-knowledge-base-facts"})
    with urllib.request.urlopen(req, timeout=30) as resp:
        return json.load(resp)


def read_providers(name, source):
    if source:
        with open(pathlib.Path(source) / PROVIDERS_DIR / name, encoding="utf-8") as f:
            return json.load(f)
    return fetch_json(f"{DATA_REPO}/{PROVIDERS_DIR}/{name}")


def count(n):
    return f"{n:,}"


def count_plus(n):
    """Round down to the hundred for prose such as "2,200+ templates"."""
    step = 100 if n >= 100 else 10
    return f"{n // step * step:,}+"


def millions(n):
    return f"{n / 1e6:.1f} million"


def pct(part, total):
    return f"{round(100 * part / total)}%"


def parse_date(value):
    return datetime.fromisoformat(value.replace("Z", "+00:00").replace(" ", "T"))


def plural(n, word):
    return f"{count(n)} {word}{'' if n == 1 else 's'}"


def support_facts(source):
    manifest = read_providers("manifest.json", source)
    overview = read_providers("overview.json", source)
    ecosystem = overview["tables"]["ecosystem"]["rows"][-1]
    adoption = overview["tables"]["adoption"]["rows"][-1]
    generated = parse_date(manifest["generated_at"])
    share_date = parse_date(adoption["completed_at"])
    files = manifest["files"]
    service_providers = files["service_providers"]["rows"]["service_providers"]
    templates = ecosystem["published_templates"]
    return {
        "stats_date": generated.strftime("%Y-%m-%d"),
        "stats_month": generated.strftime("%B %Y"),
        "dns_providers": count(ecosystem["supporting_dns_providers"]),
        "dns_provider_stacks": count(ecosystem["supporting_stacks"]),
        "known_dns_providers": count(ecosystem["known_dns_providers"]),
        "templates": count(templates),
        "templates_plus": count_plus(templates),
        "service_providers": count(service_providers),
        "service_providers_plus": count_plus(service_providers),
        "dc_share": f"{round(adoption['dc_pct'])}%",
        "dc_domains": millions(adoption["dc_domains"]),
        "scanned_domains": millions(adoption["scanned_domains"]),
        "share_date": share_date.strftime("%B %Y"),
    }


def template_repo_facts():
    stats = fetch_json(TEMPLATE_STATS_URL)
    summary = stats["summary"]
    total = summary["total_templates"]
    facts = {
        "repo_stats_date": parse_date(stats["generated_at"]).strftime("%Y-%m-%d"),
        "repo_templates": count(total),
        "repo_service_providers": count(summary["total_providers"]),
        "contributors": count(summary["total_contributors"]),
        "merged_prs": count(summary["total_merged_prs"]),
    }
    usage = stats["feature_usage"]
    for feature in usage["features"]:
        key = "feature_" + feature["name"].lower()
        facts[key] = count(feature["count"])
        facts[key + "_pct"] = pct(feature["count"], usage["total_templates"])
    for record_type in stats["record_types"]:
        facts["records_" + record_type["type"].lower()] = plural(record_type["count"], "record")
    return facts


def render(sections):
    lines = [HEADER]
    for title, facts in sections:
        lines.append(f"\n# {title}\n")
        lines.extend(f"{key}: {json.dumps(value)}\n" for key, value in facts.items())
    return "".join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--source", help="local checkout of DomainConnectSupportStatsData")
    parser.add_argument("--output", type=pathlib.Path, default=DEFAULT_OUTPUT)
    parser.add_argument("--check", action="store_true", help="exit 1 if the file is out of date")
    args = parser.parse_args()

    try:
        content = render([
            (f"DNS provider support — {DATA_REPO_URL}", support_facts(args.source)),
            (f"Template repository — {TEMPLATE_STATS_URL}", template_repo_facts()),
        ])
    except (OSError, ValueError, KeyError, IndexError, TypeError) as exc:
        print(f"update_facts: cannot read sources: {exc!r}", file=sys.stderr)
        return 2

    current = args.output.read_text(encoding="utf-8") if args.output.exists() else None
    if args.check:
        if current != content:
            print(f"update_facts: {args.output} is out of date", file=sys.stderr)
            return 1
        return 0
    if current == content:
        print(f"update_facts: {args.output} is up to date")
        return 0
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(content, encoding="utf-8")
    print(f"update_facts: updated {args.output}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
